# Expected values generated by test/torch/gen_autograd_semantics_expected.py (torch 2.15.0).
import torch
import torch.nn.functional as F

FREED = "Trying to backward through the graph a second time (or directly access saved tensors after they have already been freed). Saved intermediate values of the graph are freed when you call .backward() or autograd.grad(). Specify retain_graph=True if you need to backward through the graph a second time or if you need to access saved tensors after calling backward."
LEAF = "a leaf Variable that requires grad is being used in an in-place operation."

def X(n: int, seed: int) -> torch.Tensor:
    return (torch.arange(n, dtype=torch.float64) * 0.37 + float(seed)).sin() * 2.0 + 3.0

def close(v: List[float], exp: List[float]) -> bool:
    if len(v) != len(exp): return False
    for i in range(len(v)):
        if abs(v[i] - exp[i]) > 1e-12 * max(abs(exp[i]), 1.0): return False
    return True

def build(k: str, x: torch.Tensor) -> torch.Tensor:
    if k == "add": return (x + x).sum()
    if k == "sub": return (x - 1).sum()
    if k == "neg": return (-x).sum()
    if k == "view": return x.view(2, 2).sum()
    if k == "mean": return x.mean()
    if k == "cat": return torch.cat([x, x]).sum()
    if k == "flip": return x.flip(0).sum()
    if k == "slice": return x[1:].sum()
    if k == "expand": return x.expand(2, 4).sum()
    if k == "mulscalar": return (x * 2).sum()
    if k == "mul": return (x * x).sum()
    if k == "exp": return x.exp().sum()
    if k == "div": return (x / 2).sum()
    if k == "relu": return x.relu().sum()
    if k == "pow": return (x ** 2).sum()
    if k == "tanh": return x.tanh().sum()
    if k == "mm": return (x.view(2, 2) @ x.view(2, 2)).sum()
    return F.linear(x.view(1, 4), x.view(1, 4)).sum()

def second_backward(k: str) -> str:
    x = X(4, 1).requires_grad_()
    y = build(k, x)
    y.backward()
    try:
        y.backward()
        return "ok"
    except RuntimeError as e:
        assert str(e) == FREED
        return "ERR"

def test_backward_twice():
    cases = [("add", "ok"), ("sub", "ok"), ("neg", "ok"), ("view", "ok"), ("mean", "ok"),
             ("cat", "ok"), ("flip", "ok"), ("slice", "ok"), ("expand", "ok"),
             ("mulscalar", "ERR"), ("mul", "ERR"), ("exp", "ERR"), ("div", "ERR"), ("relu", "ERR"),
             ("pow", "ERR"), ("tanh", "ERR"), ("mm", "ERR"), ("linear", "ERR")]
    for k, exp in cases:
        r = second_backward(k)
        if r != exp:
            print("case", k, r, exp)
        assert r == exp

def test_retain_graph():
    x = X(4, 1).requires_grad_()
    y = (x * x.exp()).sum()
    y.backward(retain_graph=True)
    y.backward()
    assert close(x.grad.__val__().tolist(), [1228.5110679179888, 1699.3531065696818, 1722.5712521034914, 1277.5421645491504])
    # third time: graph was freed by the second call
    raised = False
    try:
        y.backward()
    except RuntimeError as e:
        raised = str(e) == FREED
    assert raised
    # autograd.grad frees too unless retain_graph=True
    z = (x * x).sum()
    g = torch.autograd.grad(z, [x], retain_graph=True)
    assert close(g[0].tolist(), [9.365883939231587, 9.919632245594457, 9.942876715342214, 9.432471318539235])
    g2 = torch.autograd.grad(z, [x])
    assert close(g2[0].tolist(), g[0].tolist())
    raised = False
    try:
        torch.autograd.grad(z, [x])
    except RuntimeError as e:
        raised = str(e) == FREED
    assert raised

def leaf_inplace(k: int) -> bool:
    x = X(3, 2).requires_grad_()
    try:
        if k == 0: x.add_(1)
        elif k == 1: x.mul_(2)
        elif k == 2: x.normal_()
        elif k == 3: x.fill_(1)
        elif k == 4: x.zero_()
        elif k == 5: x.copy_(torch.zeros(3, dtype=torch.float64))
        elif k == 6: x.uniform_()
        elif k == 7: x.clamp_(0.0, 1.0)
        elif k == 8: x[0] = 5.0
        elif k == 9: x += 1.0
        else: x.masked_fill_(x > 3.0, 0.0)
    except RuntimeError as e:
        assert str(e) == LEAF
        return True
    return False

def test_leaf_inplace():
    for k in range(11):
        if not leaf_inplace(k):
            print("no raise", k)
            assert False
    # allowed under no_grad, on non-leaf, and on leaves without requires_grad
    x = X(3, 2).requires_grad_()
    with torch.no_grad():
        x.add_(1.0)
        x[0] = 7.0
    assert x.tolist()[0] == 7.0
    y = x * 2
    y.add_(1.0)
    w = X(3, 2)
    w.add_(1.0)
    d = x.detach()
    d.add_(1.0)  # detach shares storage, no requires_grad
    assert x.tolist()[1] == d.tolist()[1]

def test_init_and_optim_still_work():
    torch.manual_seed(0)
    lin = torch.nn.Linear(3, 2)
    torch.nn.init.xavier_uniform_(lin.weight)
    torch.nn.init.zeros_(lin.bias)
    opt = torch.optim.SGD(lin.parameters(), lr=0.1, momentum=0.9)
    opt2 = torch.optim.Adam(lin.parameters(), lr=0.01)
    xin = torch.ones(4, 3)
    for _ in range(2):
        opt.zero_grad()
        lin(xin).pow(2).sum().backward()
        opt.step()
        opt2.step()
    assert lin.bias.tolist()[0] != 0.0

test_backward_twice()
test_retain_graph()
test_leaf_inplace()
test_init_and_optim_still_work()
print("autograd semantics ok")
